// OTP helpers shared by generate* and verify* callables.
//
// Storage scheme (locked decision, see memory-bank/decisions.md):
//   - 4-digit code, generated by crypto.randomInt
//   - Per-task random salt (16 bytes hex)
//   - SHA-256 hash of `${code}:${salt}` stored on task doc
//   - 10-minute TTL via Timestamp on task doc
//   - Plaintext returned ONCE to the customer in the generate callable
//     response; never written to Firestore in plaintext; never sent to
//     the volunteer's client; never logged.

import { createHash, randomBytes, randomInt } from 'crypto';

export const OTP_TTL_MS = 10 * 60 * 1000;
export const MAX_OTP_ATTEMPTS = 5;

export function generateOtpCode(): string {
  return randomInt(0, 10_000).toString().padStart(4, '0');
}

export function generateSalt(): string {
  return randomBytes(16).toString('hex');
}

export function hashOtp(code: string, salt: string): string {
  return createHash('sha256').update(`${code}:${salt}`).digest('hex');
}

export function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

export function evaluateOtpVerificationAttemptPure(params: {
  code: string;
  expectedHash: string;
  salt: string;
  expiresAtMs: number;
  nowMs: number;
  currentAttempts: number;
}): {
  success: boolean;
  exhausted: boolean;
  expired: boolean;
  nextAttempts: number;
  remainingAttempts: number;
  invalidateOtp: boolean;
  error?: string;
} {
  const { code, expectedHash, salt, expiresAtMs, nowMs, currentAttempts } =
    params;

  if (currentAttempts >= MAX_OTP_ATTEMPTS) {
    return {
      success: false,
      exhausted: true,
      expired: false,
      nextAttempts: currentAttempts,
      remainingAttempts: 0,
      invalidateOtp: true,
      error: 'Too many failed attempts. Ask the customer to generate a new code.',
    };
  }

  if (nowMs > expiresAtMs) {
    return {
      success: false,
      exhausted: false,
      expired: true,
      nextAttempts: currentAttempts,
      remainingAttempts: Math.max(0, MAX_OTP_ATTEMPTS - currentAttempts),
      invalidateOtp: false,
      error: 'This code has expired. Ask the customer to generate a new one.',
    };
  }

  const inputHash = hashOtp(code, salt);
  if (!constantTimeEquals(inputHash, expectedHash)) {
    const nextAttempts = currentAttempts + 1;
    const exhausted = nextAttempts >= MAX_OTP_ATTEMPTS;
    const remaining = Math.max(0, MAX_OTP_ATTEMPTS - nextAttempts);
    return {
      success: false,
      exhausted,
      expired: false,
      nextAttempts,
      remainingAttempts: remaining,
      invalidateOtp: exhausted,
      error: exhausted
        ? 'Too many failed attempts. Ask the customer to generate a new code.'
        : `That code is wrong. ${remaining} attempt${remaining === 1 ? '' : 's'} remaining.`,
    };
  }

  return {
    success: true,
    exhausted: false,
    expired: false,
    nextAttempts: 0,
    remainingAttempts: MAX_OTP_ATTEMPTS,
    invalidateOtp: true,
  };
}
